1	/**
2	 * Main Cloudflare Worker entry point for the Paperclip API.
3	 *
4	 * This file:
5	 *   1. Creates a Hono app and mounts route definitions.
6	 *   2. Implements the first-run setup gate (redirects to /setup until KV flag is set).
7	 *   3. Handles Cloudflare Queues message batches (plugin job fanout).
8	 *   4. Handles Cloudflare Cron Triggers (heartbeat sweep, budget checks, DB backup).
9	 *   5. Re-exports all Durable Object and Workflow classes so Wrangler can
10	 *      register them — they must be named exports from the Worker's main module.
11	 */
12	
13	import { Hono } from "hono";
14	import { createSetupApp } from "./setup.js";
15	import { bootCloudflare } from "../boot.js";
16	
17	// createHyperdriveDb is imported here to make it available for use when the
18	// HTTP adapter migration lands (PR #6/#7). Remove the comment and use it in
19	// the fetch handler once route modules are mounted.
20	// import { createHyperdriveDb } from "../db/hyperdrive.js";
21	
22	// ---------------------------------------------------------------------------
23	// Env — Cloudflare bindings injected at runtime
24	// ---------------------------------------------------------------------------
25	
26	export interface Env {
27	  // Databases
28	  HYPERDRIVE: { connectionString: string };
29	
30	  // Object storage
31	  PAPERCLIP_STORAGE: R2Bucket;
32	
33	  // KV — setup flags, hot config, session cache
34	  PAPERCLIP_KV: KVNamespace;
35	
36	  // Durable Object namespaces
37	  TASK_DO: DurableObjectNamespace;
38	  AGENT_RUN_DO: DurableObjectNamespace;
39	  SCHEDULER_DO: DurableObjectNamespace;
40	
41	  // Queues
42	  PAPERCLIP_QUEUE: Queue;
43	
44	  // Workflows
45	  HEARTBEAT_WORKFLOW: Workflow;
46	  PLUGIN_DISPATCH_WORKFLOW: Workflow;
47	
48	  // Vars (set in wrangler.toml [vars])
49	  DEPLOYMENT_PLATFORM: string;
50	  DEPLOYMENT_MODE: string;
51	  DEPLOYMENT_EXPOSURE: string;
52	
53	  // Secrets (set via `wrangler secret put`)
54	  // MASTER_ENCRYPTION_KEY: string  — encrypts all other secrets stored in DB
55	  // SANDBOX_BRIDGE_URL: string
56	  // SANDBOX_BRIDGE_API_KEY: string
57	}
58	
59	// ---------------------------------------------------------------------------
60	// Hono app
61	// ---------------------------------------------------------------------------
62	
63	const app = new Hono<{ Bindings: Env }>();
64	
65	// Health check — always reachable, no auth, no setup gate
66	app.get("/api/health", (c) =>
67	  c.json({
68	    status: "ok",
69	    platform: c.env.DEPLOYMENT_PLATFORM ?? "cloudflare",
70	    mode: c.env.DEPLOYMENT_MODE ?? "authenticated",
71	    ts: new Date().toISOString(),
72	  }),
73	);
74	
75	// First-run setup gate — redirect to /setup until SETUP_COMPLETED is "true"
76	app.use("*", async (c, next) => {
77	  // Allow the setup routes and health check through unconditionally
78	  if (c.req.path === "/api/health" || c.req.path.startsWith("/setup")) {
79	    return next();
80	  }
81	
82	  const setupCompleted = await c.env.PAPERCLIP_KV.get("SETUP_COMPLETED");
83	  if (setupCompleted !== "true") {
84	    return c.redirect("/setup");
85	  }
86	
87	  return next();
88	});
89	
90	// Delegate /setup/* to the setup sub-app.
91	// createSetupApp returns a Hono instance whose routes are relative to "/",
92	// so we strip the "/setup" prefix before forwarding.
93	app.all("/setup/*", async (c) => {
94	  const setupSub = createSetupApp(c.env);
95	  const url = new URL(c.req.url);
96	  // Strip leading "/setup" so routes inside the sub-app match against "/"
97	  url.pathname = url.pathname.replace(/^\/setup/, "") || "/";
98	  const rewritten = new Request(url.toString(), c.req.raw);
99	  return setupSub.fetch(rewritten);
100	});
101	
102	// Exact "/setup" (no trailing slash) — forward as "/"
103	app.all("/setup", async (c) => {
104	  const setupSub = createSetupApp(c.env);
105	  const url = new URL(c.req.url);
106	  url.pathname = "/";
107	  const rewritten = new Request(url.toString(), c.req.raw);
108	  return setupSub.fetch(rewritten);
109	});
110	
111	// ---------------------------------------------------------------------------
112	// API routes
113	// TODO: mount migrated route modules here once the HTTP adapter
114	// migration (PR #6/#7) is complete. Pattern:
115	//
116	//   import { mountRoutes } from "../http/hono-adapter.js";
117	//   import { companyRoutes } from "../../../server/src/routes/companies.js";
118	//   mountRoutes(app, companyRoutes, { db, storage, resolveActor });
119	// ---------------------------------------------------------------------------
120	
121	// Placeholder API fallthrough for any unmounted routes
122	app.all("/api/*", (c) => c.json({ error: "API route not yet mounted in CF Worker" }, 501));
123	
124	// Catch-all for non-API requests — serve the Pages SPA (handled by Cloudflare Pages
125	// when the Worker is linked to a Pages project; this handler is only reached in
126	// local `wrangler dev` mode).
127	app.all("*", (c) =>
128	  c.html(
129	    `<!DOCTYPE html>
130	<html><head><meta charset="UTF-8"><title>Paperclip</title></head>
131	<body>
132	  <p>Loading Paperclip UI... If this persists, the Pages build may not be deployed yet.</p>
133	</body></html>`,
134	  ),
135	);
136	
137	// ---------------------------------------------------------------------------
138	// Default export — Workers fetch handler
139	// ---------------------------------------------------------------------------
140	
141	export default {
142	  async fetch(request: Request, env: Env, ctx: ExecutionContext): Promise<Response> {
143	    // Boot the Cloudflare implementations on first request
144	    // (idempotent — registerStorageProvider uses a Map, safe to call multiple times)
145	    bootCloudflare(env);
146	
147	    return app.fetch(request, env, ctx);
148	  },
149	
150	  // -------------------------------------------------------------------------
151	  // Queues consumer — processes plugin job dispatch messages
152	  // -------------------------------------------------------------------------
153	  async queue(batch: MessageBatch<unknown>, env: Env): Promise<void> {
154	    for (const message of batch.messages) {
155	      const body = message.body as Record<string, unknown>;
156	      const type = body?.type as string | undefined;
157	
158	      if (type === "plugin_job_dispatch") {
159	        const pluginJobId = body.pluginJobId as string;
160	        const pluginSlug = body.pluginSlug as string;
161	        const companyId = body.companyId as string;
162	        const executorMode = (body.executorMode as "sandbox_bridge" | "container") ?? "sandbox_bridge";
163	
164	        try {
165	          await env.PLUGIN_DISPATCH_WORKFLOW.create({
166	            // Use the job ID as the Workflow instance ID for deduplication
167	            id: `plugin-job-${pluginJobId}`,
168	            params: { pluginJobId, pluginSlug, companyId, executorMode },
169	          });
170	          message.ack();
171	        } catch (err) {
172	          // Let the queue retry this message
173	          console.error(
174	            `[Queue] Failed to start PluginDispatchWorkflow for job ${pluginJobId}: ${
175	              err instanceof Error ? err.message : String(err)
176	            }`,
177	          );
178	          message.retry();
179	        }
180	        continue;
181	      }
182	
183	      if (type === "heartbeat_dispatch") {
184	        const agentId = body.agentId as string;
185	        const companyId = body.companyId as string;
186	        const runId = body.runId as string;
187	        const taskId = body.taskId as string | undefined;
188	
189	        try {
190	          await env.HEARTBEAT_WORKFLOW.create({
191	            id: `heartbeat-${runId}`,
192	            params: { agentId, companyId, runId, taskId },
193	          });
194	          message.ack();
195	        } catch (err) {
196	          console.error(
197	            `[Queue] Failed to start HeartbeatWorkflow for run ${runId}: ${
198	              err instanceof Error ? err.message : String(err)
199	            }`,
200	          );
201	          message.retry();
202	        }
203	        continue;
204	      }
205	
206	      // Unknown message type — ack to avoid infinite retries
207	      console.warn(`[Queue] Unknown message type: ${type}`);
208	      message.ack();
209	    }
210	  },
211	
212	  // -------------------------------------------------------------------------
213	  // Cron Triggers — heartbeat sweep, budget checks, DB backup
214	  // -------------------------------------------------------------------------
215	  async scheduled(event: ScheduledEvent, env: Env, _ctx: ExecutionContext): Promise<void> {
216	    const cron = event.cron;
217	    console.log(`[Cron] Firing cron: ${cron}`);
218	
219	    // TODO: replace with calls to the scheduler DO or direct internal API
220	    // endpoints once the HTTP adapter migration lands.
221	    if (cron === "*/5 * * * *") {
222	      // Heartbeat sweep — find agents that are due and enqueue heartbeat jobs
223	      // TODO: implement by querying the DB for due agents and posting to PAPERCLIP_QUEUE
224	      console.log("[Cron] Heartbeat sweep — not yet implemented");
225	    } else if (cron === "0 * * * *") {
226	      // Budget threshold check
227	      // TODO: implement by calling the internal budget service endpoint
228	      console.log("[Cron] Budget check — not yet implemented");
229	    } else if (cron === "0 3 * * *") {
230	      // Daily DB backup to R2
231	      // TODO: implement by triggering a Workflow that dumps Postgres to R2
232	      console.log("[Cron] DB backup — not yet implemented");
233	    }
234	  },
235	};
236	
237	// ---------------------------------------------------------------------------
238	// Named Durable Object + Workflow exports
239	//
240	// Wrangler requires that DO classes and Workflow classes be named exports from
241	// the Worker's main module (the file pointed to by `main` in wrangler.toml).
242	// ---------------------------------------------------------------------------
243	
244	export { TaskDO } from "../runtime/task-do.js";
245	export { AgentRunDO } from "../runtime/agent-run-do.js";
246	export { SchedulerDO } from "../scheduler/scheduler-do.js";
247	export { HeartbeatWorkflow } from "../runtime/workflows/heartbeat.js";
248	export { PluginDispatchWorkflow } from "../runtime/workflows/plugin-dispatch.js";
